public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the input array has only one element,
    // return a list containing only one list with that element
    if (nums.length == 1) {
        permutations.add(new ArrayList<>(Arrays.asList(nums[0])));
        return permutations;
    }

    // Recursive case: for each element in the input array,
    // generate all permutations of the remaining elements
    // and put the current element in each of those permutations
    for (int i = 0; i < nums.length; i++) {
        int current = nums[i];
        int[] remaining = Arrays.copyOfRange(nums, 0, nums.length - 1);
        List<List<Integer>> remainingPermutations = permute(remaining);
        for (List<Integer> permutation : remainingPermutations) {
            permutation.add(current);
        }
        permutations.addAll(remainingPermutations);
    }

    return permutations;
}

