public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int minOperations = 0;
    while (!allElementsEqual(arr)) {
        int minDiff = findMinDiffIndex(arr, n);
        int x = minDiff / 2;
        int y = minDiff % 2;
        arr[x]--;
        arr[y]++;
        minOperations++;
    }
    return minOperations;
}

private boolean allElementsEqual(int[] arr) {
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] != arr[0]) {
            return false;
        }
    }
    return true;
}

private int findMinDiffIndex(int[] arr, int n) {
    int minDiff = Integer.MAX_VALUE;
    int minDiffIndex = -1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int diff = Math.abs(arr[i] - arr[j]);
            if (diff < minDiff) {
                minDiff = diff;
                minDiffIndex = j;
            }
        }
    }
    return minDiffIndex;
}

