    // Loop through each substring of the input string
    for (int i = 0; i < s.length(); i++) {
        for (int j = i + 1; j <= s.length(); j++) {
            // Extract the substring using the substring method and check if it is already present in the map
            String substring = s.substring(i, j);
            if (!map.containsKey(substring)) {
                // If the substring is not present, add it to the map and increment the count
                map.put(substring, 1);
            } else {
                // If the substring is already present, increment the count
                map.put(substring, map.get(substring) + 1);
            }
        }
    }

    // Return the maximum number of unique substrings
    return map.size();
}

