public static int longestLine(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;
    int[][] dirs = new int[][]{{0, 1}, {1, 0}, {1, 1}, {1, -1}};

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                for (int[] dir : dirs) {
                    int currLength = 0;
                    while (true) {
                        int nextI = i + dir[0];
                        int nextJ = j + dir[1];
                        if (nextI < 0 || nextI >= rows || nextJ < 0 || nextJ >= cols || mat[nextI][nextJ] == 0) {
                            break;
                        }
                        currLength++;
                        i = nextI;
                        j = nextJ;
                    }
                    maxLength = Math.max(maxLength, currLength);
                }
            }
        }
    }
    return maxLength;
}

